float line(vec2 uv, float p){

    float x = uv.x;
    float y = uv.y;

    return (0.01+0.02/p)/abs(pow(pow(abs(x),p)+pow(abs(y),p),1./p)-0.4);
}

vec2 shear(vec2 uv, float t){

    float x = uv.x,
          y = uv.y;

    vec2 uvr;
    uvr.x = x;
    uvr.y = t*x+y;

    return uvr;
}

vec2 rotate(vec2 uv, float t){

    vec2 uvr;
    uvr.x = uv.x*cos(t)+uv.y*sin(t);
    uvr.y = -uv.x*sin(t)+uv.y*cos(t);

    return uvr;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalize pixel coordinates 
    vec2 uv = fragCoord/iResolution.xy;
    uv -= 0.5;
    uv.x *= iResolution.x/iResolution.y;

    float t = iTime;
    float p1 = pow(.1, sin(1.*t+0.)),
          p2 = pow(.1, sin(0.9*t+3.14)),
          p3 = pow(.1, sin(0.8*t)),
          p4 = pow(.1, sin(-0.7*t));

    float mask = 0.25*(line(shear(rotate(uv,t),sin(-0.7*t)), p1)+line(shear(rotate(uv,-t+3.14/2.),sin(0.5*t)),p2)+
                       line(shear(rotate(uv,t),sin(0.4*t-0.1)), p3)+line(shear(rotate(uv,t),sin(-0.3*t+0.2)), p4));


    // Output to screen
    vec3 white = vec3(1.);
    fragColor = vec4(mask*white,1.0);
}
